/// Builds one cited entry, dated with the day the source was read.
SourcedText _describe(
  String text, {
  String url = pamphletUrl,
  MosSourceKind kind = MosSourceKind.pamphlet,
}) => SourcedText(
  text: text,
  sourceUrl: url,
  retrievedOn: mosDescriptionSlice3RetrievedOn,
  sourceKind: kind,
);
